import { test, expect } from '@playwright/test';

test.describe('HTTP Status Code Reporting', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/status_codes');
  });

  test('should navigate to and display 200 status code page with correct body text', async ({ page }) => {
    // Locate and click the 200 status code link using getByRole
    const statusCode200Link = page.getByRole('link', { name: /200/i });
    await statusCode200Link.click();

    // Verify navigation to /status_codes/200
    await expect(page).toHaveURL(/status_codes\/200/);

    // Verify page body contains the expected text
    const pageBody = page.getByText(/This page returned a 200 status code/i);
    await expect(pageBody).toBeVisible();

    // Verify page title contains the expected text
    const pageTitle = page.getByText(/200 status code/i);
    await expect(pageTitle).toBeVisible();
  });

  test('should navigate to and display 404 status code page with correct body text', async ({ page }) => {
    // Locate and click the 404 status code link using getByRole
    const statusCode404Link = page.getByRole('link', { name: /404/i });
    await statusCode404Link.click();

    // Verify navigation to /status_codes/404
    await expect(page).toHaveURL(/status_codes\/404/);

    // Verify page body contains the expected text
    const pageBody = page.getByText(/This page returned a 404 status code/i);
    await expect(pageBody).toBeVisible();

    // Verify page title contains the expected text
    const pageTitle = page.getByText(/404 status code/i);
    await expect(pageTitle).toBeVisible();
  });
});
